<?php
declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/task_workflow.php';require_login_any_role(['admin','employee']);$u=current_user();$uid=(int)$u['id'];$db=get_db();task_notification_fallback($db);$view=($_GET['view']??'all')==='unread'?'unread':'all';$page=max(1,(int)($_GET['page']??1));$items=task_notification_list($db,$uid,$view,$page);$unread=task_notification_unread_count($db,$uid);
function ne(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="<?=ne(csrf_token())?>"><title>Notifications</title><style>body{margin:0;background:#f3f6fb;color:#172033;font:15px system-ui}.wrap{max-width:820px;margin:auto;padding:18px}.top,.item,.empty{background:#fff;border:1px solid #dbe3ef;border-radius:15px;padding:16px;margin-bottom:12px}.topline,.actions,.tabs{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.topline{justify-content:space-between}.tabs a,.button,button{padding:10px 13px;border-radius:9px;border:1px solid #b8c4d6;background:#fff;color:#174ea6;font:inherit;font-weight:700;text-decoration:none;min-height:42px}.tabs .active{background:#174ea6;color:#fff}.item.unread{border-left:5px solid #174ea6}.meta{color:#64748b;font-size:13px}.message{overflow-wrap:anywhere}.actions form{margin:0}.actions button{cursor:pointer}.danger{color:#b42318}.warning{color:#8a4b00}.success{color:#067647}@media(max-width:480px){.wrap{padding:9px}.actions>*{flex:1}.actions button,.button{width:100%;text-align:center}}</style></head><body><main class="wrap"><section class="top"><div class="topline"><div><a href="<?=($u['role_name']==='admin'?'admin-dashboard.php':'employee-dashboard.php')?>">← Dashboard</a><h1>Notifications</h1><p><b><?=$unread?></b> unread</p></div><?php require __DIR__.'/includes/notification_bell.php';?></div><div class="tabs"><a class="<?=$view==='unread'?'active':''?>" href="?view=unread">Unread</a><a class="<?=$view==='all'?'active':''?>" href="?view=all">All</a><button data-action="read-all">Mark all read</button></div></section><section aria-live="polite" id="notification-list"><?php if(!$items):?><div class="empty"><h2>You're all caught up</h2><p><?=$view==='unread'?'There are no unread notifications.':'There are no notifications to show.'?></p></div><?php endif;foreach($items as $n):?><article class="item <?=$n['status']==='unread'?'unread':''?>" data-id="<?=(int)$n['id']?>"><h2 class="<?=ne($n['tone'])?>"><?=ne($n['title'])?></h2><p class="message"><?=ne($n['message'])?></p><p class="meta"><?=ne($n['notification_type'])?> · Task #<?=(int)$n['source_task_id']?> · <time datetime="<?=ne($n['created_at'])?>"><?=ne($n['created_at'])?> IST</time></p><div class="actions"><a class="button" href="notification-open.php?id=<?=(int)$n['id']?>">Open exact task</a><button data-action="<?=$n['status']==='unread'?'read':'unread'?>"><?=$n['status']==='unread'?'Mark read':'Mark unread'?></button><button class="danger" data-action="dismiss">Dismiss</button></div></article><?php endforeach?></section><nav class="tabs" aria-label="Pagination"><?php if($page>1):?><a href="?view=<?=$view?>&page=<?=$page-1?>">Previous</a><?php endif;if(count($items)===20):?><a href="?view=<?=$view?>&page=<?=$page+1?>">Next</a><?php endif?></nav></main><script>document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;b.disabled=true;const card=b.closest('[data-id]');try{const r=await fetch('api/notifications.php?action='+b.dataset.action,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':document.querySelector('meta[name=csrf-token]').content},credentials:'same-origin',body:JSON.stringify(card?{id:Number(card.dataset.id)}:{})});if(r.ok){if(b.dataset.action==='dismiss'&&card)card.remove();else location.reload();if(window.TaskNotifications)window.TaskNotifications.refresh();}}catch(e){}finally{b.disabled=false;}});</script></body></html>
